from lib import *
S = SS('x108')
steps = [
    step("@PreAuthorize 与代理(@EnableMethodSecurity,非 Web 的单个程序,当前用户直接放进 SecurityContextHolder)。Svc 的实际类型是 Svc$$SpringCGLIB$$0,是 CGLIB 代理。alice(ROLE_USER)调 @PreAuthorize(\"hasRole('ADMIN')\") 的 admin():抛 AuthorizationDeniedException: Access Denied;root(ROLE_ADMIN)调:返回「admin 的数据」;SecurityContext 里没有 Authentication 时调:抛 AuthenticationCredentialsNotFoundException: An Authentication object was not found in the SecurityContext。代理带来的几个盲区:alice 调 outer(),outer 里写 this.admin() 就绕过了检查,返回 admin 的数据(类内部自调用不经过代理);同包的 package-private 方法 pkgPrivate() 仍被检查(抛 AuthorizationDeniedException);private 方法没法被代理,alice 通过 public 方法 callPriv() 调到 priv() 就执行了;注解写在接口上(Api.viaIface())同样生效,alice 被拒绝。", t=tl(S(1)), mark=lidx(S(1), 'alice 调 outer()', 'alice 调 callPriv()', '没有登录'), done=lidx(S(1), 'Svc 的实际类型', 'alice(ROLE_USER)调 admin()', 'root(ROLE_ADMIN)调 admin()', 'alice 调 pkgPrivate()', 'alice 调 viaIface()'), b=bars([['alice 直接调 admin():是否被拒绝(1=是)', 1, '是'], ['alice 通过 outer() 自调用 admin():是否被拒绝', 0, '否(绕过)'], ['alice 通过 callPriv() 调 private 方法:是否被拒绝', 0, '否(执行了)'], ['alice 调接口上注解的 viaIface():是否被拒绝', 1, '是']], 1, mark=[1, 2], done=[0, 3]), kv=KV([['实现', 'CGLIB 代理(Svc$$SpringCGLIB$$0)'], ['被拒绝', '抛 AuthorizationDeniedException: Access Denied'], ['没有 Authentication', 'AuthenticationCredentialsNotFoundException'], ['盲区', '自调用、private 方法绕过检查']], ['盲区'])),
    step("表达式里用参数与返回值。@PreAuthorize(\"#name == authentication.name\"):alice 调 mine(\"alice\") 通过,调 mine(\"bob\") 抛 AuthorizationDeniedException。@PostAuthorize(\"returnObject.owner == authentication.name\"):alice 调 doc(\"alice\") 返回 Doc;调 doc(\"bob\") 方法体已经执行了才在返回时被拒绝,抛 AuthorizationDeniedException——有副作用的方法不要用 @PostAuthorize。@PreFilter(\"filterObject.owner == authentication.name\"):alice 传入三个文档(两个属于 bob),count 方法只看到 1 个;@PostFilter 让 all() 返回的三个文档里只剩 alice 的两个。有一个静默的坑:@PreFilter 的参数是不可变列表(List.of)时,没有报错也没有过滤,count 返回 2,bob 的文档还在里面。", t=tl(S(2)), mark=lidx(S(2), 'alice 调 doc("bob")', '不可变列表'), done=lidx(S(2), 'mine("alice")', 'mine("bob")', 'doc("alice")', 'count(三个文档', 'alice 调 all()'), b=bars([['@PreFilter 传入 3 个文档(可变列表),count 看到的个数', 1, '1'], ['@PreFilter 传入不可变列表(2 个文档,1 个属于 bob),count 看到的个数', 2, '2(没过滤)'], ['@PostFilter 过滤后 all() 返回的个数(原 3 个)', 2, '2']], 2, mark=[1], done=[0, 2]), kv=KV([['#参数名', '可以在 @PreAuthorize 里引用方法参数'], ['@PostAuthorize', '方法体先执行,返回时才检查,有副作用要小心'], ['@PreFilter / @PostFilter', '按元素过滤集合'], ['不可变列表', '@PreFilter 不报错也不过滤']], ['@PostAuthorize'])),
    step("authorities 里的 FACTOR_PASSWORD。Spring Security 7 在认证成功后会给 Authentication 加一条 FACTOR_PASSWORD 权限(上一篇看到的),@PreAuthorize(\"hasAuthority('FACTOR_PASSWORD')\") 可以用它来要求用户是用密码认证过的。我手工构造的 Authentication 只有 ROLE_USER,调 factor() 抛 AuthorizationDeniedException——用 mock 或手工构造 Authentication 的测试需要自己带上这类权限。", t=tl(S(3)), mark=lidx(S(3), 'factor()'), done=[], b=bars([['authorities 里只有 ROLE_USER 时调 factor():是否被拒绝(1=是)', 1, '是']], 1, mark=[0]), kv=KV([['FACTOR_PASSWORD', 'Spring Security 7 认证成功后加上的权限'], ['hasAuthority 检查', '可以要求用密码认证过'], ['手工构造的 Authentication', '需要自己带上这条权限'], ['未验证', '多因子认证里的其他 FACTOR_*']], ['手工构造的 Authentication'])),
    step("@Secured 与 @RolesAllowed 默认不生效。默认的 @EnableMethodSecurity:alice(ROLE_USER)调 @Secured(\"ROLE_ADMIN\") 的 secured() 执行了,调 @RolesAllowed(\"ADMIN\") 的 rolesAllowed() 也执行了——没有任何检查,也没有任何提示。改成 @EnableMethodSecurity(securedEnabled = true, jsr250Enabled = true) 之后,alice 调这两个方法都抛 AuthorizationDeniedException,root 调 secured() 执行成功。从老项目迁移注解时尤其要注意。", t=tl(S(4)), mark=lidx(S(4), 'alice 调 secured() (默认的', 'alice 调 rolesAllowed() (默认的'), done=lidx(S(4), 'securedEnabled = true', 'root 调 secured() (默认'), b=bars([['默认配置:alice 调 @Secured 方法是否被拒绝(1=是)', 0, '否(执行了)'], ['默认配置:alice 调 @RolesAllowed 方法是否被拒绝', 0, '否(执行了)'], ['securedEnabled/jsr250Enabled=true:alice 调 @Secured 是否被拒绝', 1, '是'], ['securedEnabled/jsr250Enabled=true:alice 调 @RolesAllowed 是否被拒绝', 1, '是']], 1, mark=[0, 1], done=[2, 3]), kv=KV([['默认', '只认 @PreAuthorize 等,@Secured / @RolesAllowed 无效'], ['打开', '@EnableMethodSecurity(securedEnabled, jsr250Enabled)'], ['症状', '注解写了,但谁都能调,没有报错'], ['迁移', '老项目的 @Secured 要检查有没有打开']], ['默认'])),
]
A = mkartx('x108', 108, 'Spring,Security,方法级安全,PreAuthorize,AOP代理,真实验证,动画演示',
    '实测 Spring Security 7 的方法级安全:@PreAuthorize 靠 CGLIB 代理实现,类内部自调用和 private 方法绕过检查,接口上的注解有效;@PostAuthorize 在方法执行之后才拒绝;@PreFilter 对不可变列表不报错也不过滤;@Secured 与 @RolesAllowed 在默认的 @EnableMethodSecurity 下完全不生效。',
    '@PreAuthorize 为什么有时候不生效?类内部调用会不会绕过?@PostAuthorize 是方法执行前还是执行后检查?@Secured 还能用吗?这篇在 Spring Boot 4.0.8、Spring Security 7 上用同一个 Service 把各种情况都跑一遍。',
    [('绕过', '同一个类里 this.admin() 自调用不经过代理,@PreAuthorize 没有执行'), ('@Secured 无效', '默认的 @EnableMethodSecurity 下,@Secured 与 @RolesAllowed 标的方法谁都能调'), ('2 而不是 1', '@PreFilter 的参数是不可变列表时,没有过滤也没有报错')],
    [('代理与盲区', '<p>CGLIB 代理;自调用、private 方法绕过;接口上的注解有效。</p>'),
     ('表达式', '<p>参数名、返回值、集合过滤;@PostAuthorize 方法体先执行。</p>'),
     ('FACTOR_PASSWORD', '<p>Spring Security 7 认证后多出的权限,手工构造的 Authentication 要自己带上。</p>'),
     ('注解开关', '<p>@Secured、@RolesAllowed 默认不生效,要显式打开。</p>')],
    steps,
    [ENV_X + '(Spring Security 7,spring-boot-starter-security)。非 Web 模式的单个程序;当前用户由代码直接放进 SecurityContextHolder(UsernamePasswordAuthenticationToken.authenticated);「默认」与「securedEnabled / jsr250Enabled」是启动同一个程序两次(-Dx108.extra)',
     '没有验证:@Transactional 与 @PreAuthorize 的执行顺序;AspectJ 模式(@EnableMethodSecurity(mode = ASPECTJ))能否处理自调用;自定义 AuthorizationManager(见第 109 篇);@PreAuthorize 放在 Controller 方法上;@HandleAuthorizationDenied 的自定义处理;元注解;响应式方法安全;@PreFilter 对不可变集合的具体失败原因(只观察到结果)'],
    '方法级安全')
